1	import assert from "node:assert/strict";
2	import { mkdir, mkdtemp, readdir, rm, writeFile } from "node:fs/promises";
3	import { tmpdir } from "node:os";
4	import { join } from "node:path";
5	import { test } from "node:test";
6	import {
7	  InvalidKeyError,
8	  getBlob,
9	  keyToPath,
10	  listBlobs,
11	  putBlob,
12	} from "../src/storage.js";
13	
14	async function withTempDir(
15	  fn: (dataDir: string) => void | Promise<void>,
16	): Promise<void> {
17	  const dataDir = await mkdtemp(join(tmpdir(), "syncbox-storage-test-"));
18	  try {
19	    await fn(dataDir);
20	  } finally {
21	    await rm(dataDir, { recursive: true, force: true });
22	  }
23	}
24	
25	test("keyToPath resolves a plain key under the data dir", async () => {
26	  await withTempDir((dataDir) => {
27	    assert.equal(
28	      keyToPath(dataDir, "docs/readme.txt"),
29	      join(dataDir, "docs", "readme.txt"),
30	    );
31	  });
32	});
33	
34	test("keyToPath rejects a key that is exactly ..", async () => {
35	  await withTempDir((dataDir) => {
36	    assert.throws(() => keyToPath(dataDir, ".."), InvalidKeyError);
37	  });
38	});
39	
40	test("keyToPath rejects a key that walks above the root", async () => {
41	  await withTempDir((dataDir) => {
42	    assert.throws(() => keyToPath(dataDir, "../secret"), InvalidKeyError);
43	    assert.throws(() => keyToPath(dataDir, "a/../../secret"), InvalidKeyError);
44	    assert.throws(
45	      () => keyToPath(dataDir, "a/b/../../../secret"),
46	      InvalidKeyError,
47	    );
48	    assert.throws(() => keyToPath(dataDir, "..secret/../../x"), InvalidKeyError);
49	  });
50	});
51	
52	test("keyToPath rejects an absolute path key", async () => {
53	  await withTempDir((dataDir) => {
54	    assert.throws(() => keyToPath(dataDir, "/etc/passwd"), InvalidKeyError);
55	  });
56	});
57	
58	test("keyToPath rejects an empty key", async () => {
59	  await withTempDir((dataDir) => {
60	    assert.throws(() => keyToPath(dataDir, ""), InvalidKeyError);
61	  });
62	});
63	
64	test("keyToPath rejects a key that resolves to the root itself", async () => {
65	  await withTempDir((dataDir) => {
66	    assert.throws(() => keyToPath(dataDir, "."), InvalidKeyError);
67	  });
68	});
69	
70	test("keyToPath rejects a key containing a null byte", async () => {
71	  await withTempDir((dataDir) => {
72	    assert.throws(() => keyToPath(dataDir, "a\0b"), InvalidKeyError);
73	  });
74	});
75	
76	test("keyToPath rejects a key with an unpaired surrogate", async () => {
77	  await withTempDir((dataDir) => {
78	    assert.throws(
79	      () => keyToPath(dataDir, "bad-\uD800-name"),
80	      InvalidKeyError,
81	    );
82	  });
83	});
84	
85	test("keyToPath accepts a .. segment that stays inside the root", async () => {
86	  await withTempDir((dataDir) => {
87	    assert.equal(keyToPath(dataDir, "a/../b.txt"), join(dataDir, "b.txt"));
88	  });
89	});
90	
91	test("putBlob does not leave a temp file behind after a successful write", async () => {
92	  await withTempDir(async (dataDir) => {
93	    await putBlob(dataDir, "file.txt", Buffer.from("content"));
94	
95	    const entries = await readdir(dataDir);
96	    assert.deepEqual(entries, ["file.txt"]);
97	  });
98	});
99	
100	test("putBlob cleans up its temp file when the final rename fails", async () => {
101	  await withTempDir(async (dataDir) => {
102	    const key = "conflict";
103	    // Occupy the target path with a directory so rename(tmp -> key) fails.
104	    await mkdir(join(dataDir, key));
105	
106	    // A structurally valid key can still be unwritable for OS-level reasons
107	    // (here: the target is occupied by a directory). That must surface as
108	    // the same InvalidKeyError structural rejection uses, not a raw fs error.
109	    await assert.rejects(() => putBlob(dataDir, key, Buffer.from("x")), InvalidKeyError);
110	
111	    const entries = await readdir(dataDir);
112	    assert.deepEqual(entries, [key]);
113	    for (const entry of await readdir(join(dataDir, key))) {
114	      assert.fail(`unexpected leftover inside ${key}: ${entry}`);
115	    }
116	  });
117	});
118	
119	test("putBlob rejects with InvalidKeyError when a parent path segment is occupied by a file", async () => {
120	  await withTempDir(async (dataDir) => {
121	    // "blocked" exists as a plain file, so mkdir(dirname("blocked/nested.txt"))
122	    // fails at the OS level (ENOTDIR) even though the key itself passed every
123	    // structural check. This must still map to InvalidKeyError, not a raw,
124	    // uncaught fs error.
125	    await writeFile(join(dataDir, "blocked"), Buffer.from("occupied"));
126	
127	    await assert.rejects(
128	      () => putBlob(dataDir, "blocked/nested.txt", Buffer.from("x")),
129	      InvalidKeyError,
130	    );
131	  });
132	});
133	
134	test("concurrent putBlob calls to different keys do not interfere", async () => {
135	  await withTempDir(async (dataDir) => {
136	    const a = Buffer.alloc(1024 * 1024, 0x01);
137	    const b = Buffer.alloc(1024 * 1024, 0x02);
138	
139	    await Promise.all([
140	      putBlob(dataDir, "a.bin", a),
141	      putBlob(dataDir, "b.bin", b),
142	    ]);
143	
144	    assert.deepEqual(await getBlob(dataDir, "a.bin"), a);
145	    assert.deepEqual(await getBlob(dataDir, "b.bin"), b);
146	  });
147	});
148	
149	test("concurrent putBlob calls to the same key never produce corrupted content", async () => {
150	  await withTempDir(async (dataDir) => {
151	    const key = "race.bin";
152	    const variants = [
153	      Buffer.alloc(1024 * 1024, 0xaa),
154	      Buffer.alloc(1024 * 1024 + 7, 0xbb),
155	      Buffer.alloc(1024 * 1024 - 3, 0xcc),
156	    ];
157	
158	    await Promise.all(variants.map((content) => putBlob(dataDir, key, content)));
159	
160	    const final = await getBlob(dataDir, key);
161	    assert.ok(final);
162	    assert.ok(
163	      variants.some((v) => v.equals(final)),
164	      "final content must be exactly one of the concurrent writes, not a mix",
165	    );
166	
167	    const entries = await readdir(dataDir);
168	    assert.deepEqual(entries, [key]);
169	  });
170	});
171	
172	test("a GET racing a PUT of the same key sees fully old or fully new content, never partial", async () => {
173	  await withTempDir(async (dataDir) => {
174	    const key = "race-read.bin";
175	    const oldContent = Buffer.alloc(4 * 1024 * 1024, 0xaa);
176	    const newContent = Buffer.alloc(4 * 1024 * 1024, 0xbb);
177	    await putBlob(dataDir, key, oldContent);
