test("DELETE /blobs/{key} rejects a percent-encoded .. escape with 400", async () => {
  await withServer(async (baseUrl) => {
    const res = await request(`${baseUrl}/blobs/%2e%2e%2fsecret.txt`, {
      method: "DELETE",
    });
