test("directory traversal attempts do not write files outside the data dir", async () => {
  await withServer(async (baseUrl, dataDir) => {
    await requestRawPath(baseUrl, "/blobs/../escape.txt", "PUT");
    await request(
      `${baseUrl}/blobs/%2e%2e%2fescape2.txt`,
      { method: "PUT" },
      Buffer.from("x"),
